import React, { forwardRef } from 'react';
import styled from 'styled-components';

import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';

//#region Typings
/** Accepted properties for the TitleBar Suffix */
export interface TitleBarSuffixProps extends StylingProps, DataTestId {
  /** Elements to be displayed in the TitleBar Suffix slot. */
  children: React.ReactNode;
}
//#endregion

//#region Styled Components
const StyledSuffixWrapper = /* @__PURE__ */ styled('div')({
  maxWidth: '100%',
});
//#endregion

/** TitleBar Suffix component */
export const Suffix = forwardRef<HTMLDivElement, TitleBarSuffixProps>(
  (props, forwardedRef) => {
    const {
      children,
      className: consumerClassName,
      style: consumerStyle,
      'data-testid': dataTestId,
    }: TitleBarSuffixProps = props;

    return (
      <StyledSuffixWrapper
        ref={forwardedRef}
        className={consumerClassName}
        style={consumerStyle}
        data-testid={dataTestId}
      >
        {children}
      </StyledSuffixWrapper>
    );
  },
);
